// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Login watch: is each account still logged in
// Flo: no flag = read the saved login state (no network) and, when the last look is older than aliv_look_hour, one read-only look at ONE account per run (a failed look retries in 1 h, so it never starves the other account) > --live = look now > a dead login saves the state, alerts the owner (toast, 6 h gap) and exits 3; a good login or `za-zalo-webs login` saves ok
// I/O: Ctx (caller) > one line per account; file <stat>/za-alive.txt "<ms> <ok|needlogin> <last alert ms>"; exit 0 ok · 1 unknown · 3 needs login
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const file = @import("st-stor-file.zig"); const snap = @import("ru-page-snap.zig"); const halt = @import("ru-safe-halt.zig"); const lab = @import("cf-labl-load.zig"); const noti = @import("ru-noti-send.zig"); const pace = @import("ru-huma-pace.zig");
const CF = .{ .name = "za-alive.txt", .tick = 2000, .wait = 30000, .cool = 6 * 3600 * 1000, .ok = "ok", .dead = "needlogin" };
pub const Mark = struct { state: []const u8 = "", noted: i64 = 0, at: i64 = 0 };
var looked: bool = false;
fn markPath(ctx: *ctxz.Ctx) ![]const u8 { return std.fs.path.join(ctx.allo, &.{ ctx.stat, CF.name }); }
pub fn markPut(ctx: *ctxz.Ctx, state: []const u8, noted: i64) void { markAt(ctx, state, noted, ctxz.nowMs(ctx)); }
fn markAt(ctx: *ctxz.Ctx, state: []const u8, noted: i64, at: i64) void { if (ctx.args.mock) return; const path = markPath(ctx) catch return; const body = std.fmt.allocPrint(ctx.allo, "{d} {s} {d}\n", .{ at, state, noted }) catch return; file.fileAtom(ctx.allo, ctx.iozz, path, body) catch {}; }
pub fn markParse(body: []const u8) Mark { var iter = std.mem.tokenizeAny(u8, body, " \r\n"); const at = std.fmt.parseInt(i64, iter.next() orelse return .{}, 10) catch 0; const state = iter.next() orelse return .{}; const noted = std.fmt.parseInt(i64, iter.next() orelse "0", 10) catch 0; return .{ .state = state, .noted = noted, .at = at }; }
pub fn dueLook(mrk: Mark, now: i64, hours: u32) bool { if (std.mem.eql(u8, mrk.state, CF.dead)) return false; return mrk.at == 0 or now - mrk.at >= @as(i64, hours) * 3600 * 1000; }
pub fn markGet(ctx: *ctxz.Ctx) Mark { const path = markPath(ctx) catch return .{}; const body = file.fileRead(ctx.allo, ctx.iozz, path, 256) catch return .{}; return markParse(body); }
fn loginCmd(ctx: *ctxz.Ctx) []const u8 { const dirz = std.process.executableDirPathAlloc(ctx.iozz, ctx.allo) catch return "za-zalo-webs"; const exe = std.fs.path.join(ctx.allo, &.{ dirz, if (@import("builtin").os.tag == .windows) "za-zalo-webs.exe" else "za-zalo-webs" }) catch return "za-zalo-webs"; return std.fmt.allocPrint(ctx.allo, "\"{s}\"", .{exe}) catch "za-zalo-webs"; }
fn tellDead(ctx: *ctxz.Ctx, noted: i64) !void { const now = ctxz.nowMs(ctx); const line = try std.fmt.allocPrint(ctx.allo, "account {s} needs login: run {s} login --acct {s}", .{ ctx.acct, loginCmd(ctx), ctx.acct }); try ctxz.emitf(ctx, "{s}\n", .{line}); if (noted > 0 and now - noted < CF.cool) { markPut(ctx, CF.dead, noted); return; } _ = noti.send(ctx.allo, ctx.iozz, ctx.cfg, ctx.stat, line, now, !ctx.args.mock) catch {}; markPut(ctx, CF.dead, now); }
fn liveChek(ctx: *ctxz.Ctx) !u8 { if (pace.quietNow(ctxz.nowMs(ctx), ctx.cfg.loca_utcz_mins, ctx.cfg.quie_hour_rang[0], ctx.cfg.quie_hour_rang[1])) { try ctxz.emitf(ctx, "account {s}: quiet hours, check skipped\n", .{ctx.acct}); return 0; } var live = try ctxz.openLive(ctx, false); defer live.close(); var reg = try lab.load(ctx.allo, ctx.iozz, ctx.cfg.labl_file_path); var spent: u64 = 0; while (spent <= CF.wait) : (spent += CF.tick) { var aren = std.heap.ArenaAllocator.init(ctx.init.gpa); defer aren.deinit(); const txt = snap.pageText(aren.allocator(), live.conn) catch ""; const ver = try halt.check(aren.allocator(), ctx.cfg, &reg, txt); switch (ver.kind) { .okay => { if (txt.len > 0) { markPut(ctx, CF.ok, 0); try ctxz.emitf(ctx, "account {s}: logged in\n", .{ctx.acct}); return 0; } }, .login => { try tellDead(ctx, markGet(ctx).noted); return 3; }, .need, .unsf => { ctxz.alert(ctx, ver.word); return error.Halted; } } std.Io.sleep(ctx.iozz, .fromMilliseconds(CF.tick), .awake) catch {}; } try ctxz.emitf(ctx, "account {s}: unknown (page did not draw in time)\n", .{ctx.acct}); return 1; }
pub fn aliveRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.mode == .live or ctx.args.mode == .force) return liveChek(ctx); const mrk = markGet(ctx); if (!looked and !ctx.args.mock and dueLook(mrk, ctxz.nowMs(ctx), ctx.cfg.aliv_look_hour) and !pace.quietNow(ctxz.nowMs(ctx), ctx.cfg.loca_utcz_mins, ctx.cfg.quie_hour_rang[0], ctx.cfg.quie_hour_rang[1])) { looked = true; markAt(ctx, if (mrk.state.len == 0) "unknown" else mrk.state, mrk.noted, ctxz.nowMs(ctx) - (@as(i64, ctx.cfg.aliv_look_hour) - 1) * 3600 * 1000); return liveChek(ctx); } if (std.mem.eql(u8, mrk.state, CF.dead)) { try tellDead(ctx, mrk.noted); return 3; } try ctxz.emitf(ctx, "account {s}: {s}\n", .{ ctx.acct, if (mrk.state.len == 0) "unknown (not checked yet)" else mrk.state }); return 0; }
